import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷山小過","description":"周易折中 - 雷山小過","frontmatter":{"title":"雷山小過","description":"周易折中 - 雷山小過"},"headers":[],"relativePath":"classics/zhezhong/068.md","filePath":"classics/zhezhong/068.md"}'),h={name:"classics/zhezhong/068.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="雷山小過" tabindex="-1">雷山小過 <a class="header-anchor" href="#雷山小過" aria-label="Permalink to “雷山小過”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈小過序卦〉：“有其信者必行之，故受之以《小過》。人之所信，則必行；行，則過也。《小過》所以繼《中孚》也。為卦，山上有雷，雷振於高，其聲過常，故為《小過》。又陰居尊位，陽失位而不中，小者過其常也。葢為小者過，又為小事過，又為過之小。”</p><p>小過：亨，利貞。可小事，不可大事。飛鳥遺之音，不宜上，宜下，大吉。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>小謂陰也，為卦四陰在外，二陽在內，陰多於陽，小者過也。既過於陽，可以亨矣，然必利於守貞，則又不可以不戒也。卦之二五皆以柔而得中，故可小事；三四皆以剛失位而不中，故不可大事。卦體內實外虛，如鳥之飛，其聲下而不上，故能致飛鳥遺音之應，則宜下而大吉，亦不可大事之類也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>過者，過其常也。若矯枉而過正，過所以就正也。事有時而當然，有待過而後能亨者，故小過自有亨義。利貞者，過之道利於貞也，不失時宜之謂正。過所以求就中也，所過者小事也，事之大者豈可過也？於大過論之詳矣。飛鳥遺之音，謂過之不遠也。不宜上，宜下，謂宜順也，順則大吉。過以就之，葢順理也，過而順理，其吉必大。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：飛鳥遺其音，聲哀以求處，上愈無所適，下則得安。愈上則愈窮，莫若飛鳥也。</p></li><li><p>孔氏穎達曰：過之小事，謂之小過，即行過乎恭、喪過乎哀之例是也。禇氏雲：謂小人之行小有過差，君子為過厚之行以矯之，如晏子狐裘之比也。過為小事，道乃可通，故曰“小過亨，利貞者，矯世勵俗，利在歸正也”。可小事不可大事者，小有過差，惟可矯以小事，不可正以大事。飛鳥遺之音，不宜上宜下大吉者，飛鳥聲哀以求處，上過則愈無所適，過下則不失其安。譬君子處過差之時，為過矯之行，順則執卑守下，逆則犯君陵上，故以順逆類鳥之上下也。</p></li><li><p>呂氏大臨曰：小過，過於小者也。君子之道皆以濟其不及，然後可以㑹於中。大過以濟其大不及，小過以濟其小不及者，濟所以亨也。飛鳥不宜上宜下，上窮而下有止也。過奢過慢則兇，不宜上也；過恭過儉則吉，宜下也。</p></li><li><p>朱子語類雲：小過是過於慈惠之類，大過則是剛嚴果毅底氣象。小過是小事過，又是過於小，如行過乎恭、喪過乎哀、用過乎儉，皆是過於小，退後一步自貶底意思。</p></li><li><p>俞氏琰曰：小過之時，可過者小事而已，大事則不可過也。</p></li><li><p>林氏希元曰：小過不當以人類言，當以事類言。觀大象，本義曰“三者之過皆小者之過”，可過於小而不可過於大，可以小過而不可以甚過。又曰：“彖所謂可小事而宜下，其意可見矣。”小過亨者，小事過而亨也。曰“利貞”，深戒佔者之辭。可小事不可大事，是申小過之義。言此卦之義可以施於小事，不可施於大事。不宜上宜下，又是申利貞之義。飛鳥遺之音者，卦有飛鳥之象，卦示以兆，如飛鳥之遺以音也。上下二字是借鳥飛之上下以切人事。飛鳥相呼雲“不宜上宜下”，在飛鳥則上無止戾，下有棲宿；在人事則髙亢者失正而遠於理，卑約者得正而近乎情，是以大吉也。</p></li><li><p>陸氏銓曰：君子雖行貴得中，事期當可，然勢有極重時，須損餘以補缺。事必矯枉而後平，即夫子所謂寧儉甯戚之意。理所當過，即是時中。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>大過者，大事過也；小過者，小事過也。大事謂關係天下國家之事，小事謂日用常行之事。道雖貴中，而有時而過者，過所以為中也。當過而過，然後可以通行，故有亨道而利於正也。可小事不可大事，是申小過之義，言此卦之義可以施於小事，不可施於大事。不宜上宜下，又是申利貞之義。飛鳥遺之音，者卦有飛鳥之象，卦示以兆，如飛鳥之遺以音也。上下二字是借鳥飛之上下以切人事。飛鳥相呼雲“不宜上宜下”，在飛鳥則上無止戾，下有棲宿；在人事則髙亢者失正而遠於理，卑約者得正而近乎情，是以大吉也。</p><p>象曰：山上有雷，小過；君子以行過乎恭，喪過乎哀，用過乎儉</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>山上有雷，其聲小過。三者之過，皆小者之過。可過於小而不可過於大，可以小過而不可甚過。彖所謂“可小事而宜下者也”。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>雷震於山上，其聲過常，故為小過。天下之事，有時當過而不可過甚，故為小過。君子觀小過之象，事之宜過者則勉之。行過乎恭，喪過乎哀，用過乎儉是也。當過而過，乃其宜也；不當過而過，則過矣。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：小人過差，失在慢易奢侈，故君子矯之以行過乎恭，喪過乎哀，用過乎儉也。</p></li><li><p>張子曰 ：過恭、哀、儉，皆宜下之義。</p></li><li><p>鼂氏說之曰 ：時有舉趾高之莫敖，故正考父矯之以循牆；時有短喪之宰予，故高柴矯之以泣血；時有三歸反坫之管仲，故晏子矯之以敝裘。雖非中行，亦足以矯時厲俗。</p></li><li><p>趙氏彥肅曰 ：恭、哀、儉多不及，過之而後中。</p></li><li><p>楊氏啟新曰 ：過恭、過哀、過儉，此豈不為高世絕俗之行而過乎人？但其所過者以收斂卑下為過，故但可言小過而不可言大過也。案雷出地則聲方發達而大，及至山上則聲漸收斂而微，故有平地風雷大作而高山之上不覺者，此小過之義也。</p></li></ul><p>彖曰：小過 小者過而亨也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦名義與其辭。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>陽大陰小，陰得位，剛失位而不中，是小者過也。故為小事過，過之小。小者與小事有時而當過，過之亦小，故為小過。事固有待過而後能亨者，過之所以能亨也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰：順時矯俗，雖過而通。</p></li><li><p>朱氏震曰：小過，小者過也。葢事有失之於偏，矯其失必待小有所過，然後偏者反於中。謂之過者，比之常理則過也，過反於中，則其用不窮而亨矣。故曰“小者過而亨也”。</p></li><li><p>王氏宗傳曰：言以過故亨也。天下固有越常救失之事，如象所謂“過乎恭”、“過乎哀”、“過乎儉”是也。不有所過，安能亨哉？故曰“小者過而亨也”。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>此釋義與“遁而亨也”同。遁非得已之事，然必遁而後亨；小過亦非得已之事，然必過而後亨，故其釋義同也。</p><p>過以利貞，與時行也</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>過而利於貞，謂與時行也。時當過而過，乃非過也，時之宜也，乃所謂正也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘇氏軾曰：彖之所謂“利貞”，即象之所謂“過乎恭儉與哀”者，時當然也。</p></li><li><p>朱氏震曰：君子制事以天下之正理，所以小過者，時而已。故曰“過以利貞，與時行也”。</p></li><li><p>蔡氏淵曰：與時行，謂隨小過之時而用其正也。</p></li><li><p>龔氏煥曰：道貴得中，過非所尚。然隨時之宜，施當其可，則過也乃所以為中也。故曰“過以利貞，與時行也”。與時行而不失其貞，則過非過矣。</p></li></ul><p>柔得中是以小事吉也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以二五言。</p><p>剛失位而不中是以不可大事也</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>以三四言。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>小過之道，於小事有過則吉者。而彖以卦才言吉義，柔得中，二五居中也。陰柔得位，能致小事吉耳，不能濟大事也。剛失位而不中，是以不可大事。大事非剛陽之才不能濟，三不中，四失位，是以不可大事。小過之時，自不可大事，而卦才又不堪大事，與時合也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰：柔順之人能行小事，柔而得中是行小中時，故曰“小事吉也”。剛健之人能行大事，失位不中是行大不中時，故曰“不可大事也”。</p></li><li><p>朱氏震曰：於小事有過而不失其正則吉，柔得中也。作大事非剛得位得中不能濟，失位則無所用其剛，不中則才過乎剛，是以小過之時不可作大事也。</p></li><li><p>胡氏炳文曰：矯天下之枉者，以過為正。然剛過而中為大過，柔得中為小過。是則事有當過者，而皆不可外乎中也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>任大事貴剛，取其強毅可以遺大投艱也；處小事貴柔，取其畏慎為能矜細勤小也。二者皆因乎時，得中者適乎時之謂也。此卦柔得中，剛失位而不中，則有行小事適時而行大事則非其時之象。</p><p>有飛鳥之象焉，飛鳥遺之音，不宜上，宜下，大吉；上逆而下順也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>以卦體言。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>有飛鳥之象焉，此一句不類彖體，蓋解者之辭誤入彖中。中剛外柔，飛鳥之象，卦有此象，故就飛鳥為義。事有時而當過，所以從宜，然豈可甚過也？如過恭、過哀、過儉，大過則不可。所以在小過也，所過當如飛鳥之遺音。鳥飛迅疾，聲出而身已過，然豈能相遠也？事之當過者亦如是，身不能甚遠於聲，事不可遠過其常，在得宜耳。不宜上，宜下，更就鳥音取宜順之義。過之道當如飛鳥之遺音，夫聲逆而上則難，順而下則易。故在髙則大過，山上有雷所以為過也。過之道順行則吉，如飛鳥之遺音，宜順也。所以過者為順乎宜也，能順乎宜所以大吉。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：施過於不順，兇莫大焉；施過於順，過更變而為吉也。</p></li><li><p>胡氏瑗曰：四陰在外，二陽在內，是內實外虛，故有飛鳥之象也。飛鳥翔空無所依著，愈上則愈窮，是上則逆也；下附物則身可安，是下則順也。猶君子之人過行其事以矯世勵俗，必下附人情，亦宜下而不宜上也。</p></li><li><p>朱氏震曰：上逆也，故不宜上；下順也，故宜下。小過之時，事有時而當過，所以從宜，不可過越已甚，不然必兇也。</p></li><li><p>俞氏琰曰：溯風而上為逆，隨風而下為順。</p></li><li><p>方氏時化曰：聖人因此卦有飛鳥之象，遂即象以戒之曰：“飛鳥有遺音。”雲“遺音如何言不宜上，宜下大吉”雲耳。夫鳥上飛則逆，下飛則順，其大致也。今自謂宜下而不宜上焉，實為二陽諷也。</p></li><li><p>吳氏曰慎曰：以卦體言，陰乘陽為逆，承陽為順。四陰分居上下，有逆順之象。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>四陽居中則有棟樑之象，四陰居外則有羽毛之象。君子之任大事，則為天下棟樑；修細行，則為天下羽儀。此二卦取象之意也。然以其陰陽皆過多也，故謂之大過、小過。事固有過以為中者，無嫌於過也，然必過而不失其中，乃歸於無過。故棟則惡其太剛而折，太重而橈，故宜隆於上不可橈於下也；羽則惡其柔而無立，輕而不戢，故宜就於下不可颺於上也。大過之彖曰：“剛過而中，不橈乎下，斯為剛之中矣。”小過之彖曰：“柔得中，不宜上，宜下，斯為柔之中矣。”</p><p>初六：飛鳥以兇</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>初六陰柔，上應九四，又居過時上而不下者也。飛鳥遺音，不宜上宜下，故其象佔如此。郭璞《洞林》佔得此者，或致羽蟲之孽。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>初六陰柔在下，小人之象，又上應於四。四復動體，小人躁易，而上有應，助於所當過，必至過甚。況不當過而過，其過如飛鳥之迅疾，所以兇也。躁疾如是，所以過之速且遠，救止莫及也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：小過之義，上逆下順。而初應在上卦，進而之逆，同於飛鳥無所錯足，故曰“飛鳥以兇”。</p></li><li><p>胡氏瑗曰：小過之時不宜上位，在下而志愈上，故獲兇也。</p></li><li><p>項氏安世曰：初上二爻陰過而不得中，是以兇也。以卦象觀之，二爻皆當鳥翅之末。初六在艮之下，當止而反飛，以飛致兇，故曰“飛鳥以兇”。上六居震之極，其飛已高，則麗於綱罟，故曰“飛鳥離之兇”。</p></li><li><p>龔氏煥曰：大過卦辭以棟為象，而三四兩爻亦以棟言；小過卦辭以鳥為象，而初上兩爻亦以鳥言。大過陽過於中，而三四又陽之中也；小過陰過於外，初上又陰之外也。</p></li><li><p>胡氏炳文曰：大過有棟橈象，棟之用在中，故於三四言之。小過有飛鳥象，鳥之用在翼，故於初上言之。然初二五上皆翼也，獨初上言之何耶？鳥飛不在翼而在翰，初上其翰也。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>大過象棟者兩爻，小過象飛鳥者亦兩爻。然大過宜隆不宜橈，則四居上吉，三居下兇，宜矣。小過之鳥宜下不宜上，初居下應吉而反兇者，何也？蓋屋之中棟惟一而已，四之象獨當之；鳥之翼則有兩，初與上之象皆當之也。初於時則未過，於位則處下，如鳥之正當棲宿者，乃不能自禁而飛，其兇也豈非自取乎？</p><p>象曰：飛鳥以兇，不可如何也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>其過之疾如飛鳥之迅，豈容救止也？兇其宜矣，不可如何，無所用其力也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>何氏楷曰 ：以兇者自納於兇也，孽由己作，可如何哉？</li></ul><p>六二：過其祖，遇其妣；不及其君，遇其臣，無咎。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>六二柔順中正，進則過三四而遇六五，是過陽而反遇陰也。如此則不及六五而自得其分，是不及君而適遇其臣也。皆過而不過，守正得中之意，無咎之道也。故其象佔如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>陽之在上者，父之象；尊於父者，祖之象。四在三上，故為祖。二與五居相應之地，同有柔中之德，志不從於三四，故過四而遇五，是過其祖也。五陰而尊，祖妣之象。與二同德相應，在他卦則陰陽相求，過之時必過其常，故異也。無所不過，故二從五，亦戒其過。不及其君遇其臣，謂上進而不陵及於君，適當臣道，則無咎也。遇，當也。過臣之分，則其咎可知。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰：六二或過或不及，皆適當其時與分，而不愆於中焉。此在過之道，為無過也，故曰無咎。</p></li><li><p>俞氏琰曰：遇妣而過於祖，雖過之，君子不以為過也。遇臣則不可過於君，故曰“不及其君遇其臣”。彖言“可小事不可大事，不宜上宜下”，而六二柔順中正，故其象如此，其佔無咎。</p></li><li><p>張氏振淵曰：祖妣只作陰陽象，陽亢而陰順也。過祖遇妣，是去陽而就陰，去亢而從順。如此則不陵及於君，適當臣道之常矣。不及其君遇其臣，宜下宜順也。</p></li><li><p>吳氏曰愼曰：六二中正而爻辭以過不及言之，葢當過而過，當不及而不及，此權之所以取中，而卒無過不及之偏矣。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>古者重昭穆，故孫則祔於祖，孫婦則袝於祖姑。晉之王母，此爻之“妣”，皆謂祖姑也。兩陰相應，故取妣婦相配之象。凡《易》之義，陰陽有應者則為君臣、為夫婦，取其耦配也；無應者則或為父子、或為等夷、或為嫡媵、或為妣婦，取其同類也。此爻二五皆柔，有妣婦之配，無君臣之交，故取“遇妣不及其君”為義。孫行而附於祖列，疑其過矣，然禮所當然是適得其分也。無應於君者，不敢仰幹於君之象，然守柔居下，是臣節不失也。以人事類之，則事之可過者，過而得其恭順之體；事之必不可過者，不及而安於名分之常。夫子之言“麻冕拜下”，意正如此也。小過之義主於過恭過儉，妻道也，臣道也。二當其位而有中正之德，故能權衡於過不及而得其中。於六爻中，為最善。</p><p>象曰：不及其君臣，不可過也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>所以不及君而還遇臣者，以臣不可過故也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>過之時，事無不過其常。故於上進，則戒及其君臣，不可過臣之分也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰 ：小者有時而可過，臣之於君，不可過也。</li></ul><p>九三：弗過防之，從或戕之，兇。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>小過之時，事每當過然後得中。九三以剛居正，眾陰所欲害者也。而自恃其剛，不肯過為之備，故其象佔如此。若佔者能過防之，則可以免矣。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>小過，陰過陽失位之時，三獨居正。然在下無所能為，而為陰所忌惡。故有當過者，在過防於小人。若弗過防之，則或從而戕害之矣，如是則兇也。三於陰過之時，以陽居剛，過於剛也。既戒之過防，則過剛亦在所戒矣。防小人之道，正己為先。三不失正，故無必兇之義。能過防則免矣。三居下之上，居上為下，皆如是也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><p>楊氏啟新曰：此言當過於防，而九三不知時也。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>小過者，小事過也。小事過者，敬小慎微之義也。九三過剛，違於斯義矣，故為“不過於周防而或遇戕害”之象。《傳》曰：“君子能勤小物，故無大患。”此爻之義也。</p><p>象曰：從或戕之，兇，如何也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>陰過之時，必害於陽。小人道盛，必害君子。當過為之防，防之不至，則為其所戕矣。故曰兇，如何也？言其甚也。</p><p>九四：無咎，弗過遇之，往厲必戒，勿用永貞。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>當過之時，以剛處柔，過乎恭矣。無咎之道也。弗過遇之，言弗過於剛而適合其宜也。往則過矣，故有厲而當戒。陽性堅剛，故又戒以勿用永貞。言當隨時之宜，不可固守也。或曰：弗過遇之，若以六二爻例，則當如此說；若依九三爻例，則過遇當如過防之義。未詳孰是，當闕以俟知者。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>四當小過之時，以剛處柔，剛不過也是以無咎。既弗過，則合其宜矣，故云遇之，謂得其道也。若往則有危，必當戒懼也，往去柔而以剛進也。勿用永貞，陽性堅剛，故戒以隨宜不可固守也。方陰過之時，陽剛失位，則君子當隨時順處，不可固守其常也。四居高位而無上下之交，雖比五應初，方陰過之時，彼豈肯從陽也，故往則有厲。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>朱子語類雲：過遇猶言加意待之也，與九三“弗過防之”文體正同。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>彖傳三四皆剛失位而不中，然九三純剛故兇，九四居柔故有無咎之義。然質本剛也，故又戒以當過遇之為善。遇者，合人情就事理。過遇，朱子所謂加意待之者是也。若不能過遇之，則往而有危，所當以為戒而不可固執而不變者，是小過之時義也。</p><p>象曰：弗過遇之，位不當也；往厲必戒，終不可長也</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>爻義未明，此亦當闕。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>位不當，謂處柔。九四當過之時，不過剛而反居柔，乃得其宜，故曰遇之，遇其宜也。以九居四位不當也，居柔乃遇其宜也。當陰過之時，陽退縮自保足矣，終豈能長而盛也？故往則有危，必當戒也。“長”上聲作平聲，則大失易意，以夬與剝觀之可見。與夬之象文同而音異也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>錢氏一本曰 ：三四皆失位，故特明其位不當。三防，四遇，亦皆宜下。三從或戕，四往必戒，亦皆不宜上。</li></ul><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>位不當，即所謂剛失位而不中者。惟剛失位而不中，故戒以當過遇之，不然則有危矣。豈可長執此而不知變乎？</p><p>六五：密雲不雨，自我西郊。公弋取彼在穴。</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>以陰居尊，又當陰過之時，不能有為。而弋取六二以為助，故有此象。在穴，陰物也。兩陰相得，其不能濟大事可知。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>五以陰柔居尊位，雖欲過為，豈能成功？如宻雲而不能成雨，所以不能成雨自西郊故也。陰不能成雨，小畜卦中已解。公弋取彼在穴，弋射取之也。射止是射，弋有取義。穴，山中之空，中虛乃空也。在穴，指六二也。五與二本非相應，乃弋而取之。五當位，故云公，謂公上也。同類相取，雖得之，兩陰豈能濟大事乎？猶密雲之不能成雨也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰：小過有飛鳥之象，故因曰“取彼在穴”。</p></li><li><p>胡氏瑗曰：弋者，所以射高也；穴者，所以隱伏而在下也。公以弋繳而取穴中之物，猶聖賢雖過行其事，意在矯下也。</p></li><li><p>姚氏舜牧曰：時值小過，宜下不宜上。陰至於五，過甚矣。其所居者尊位也，挾勢自亢，澤不下究。雲雖密而不雨，自我西郊故耳。當此之時，欲沛膏澤於生民，必湏下求巖穴之士以為輔，乃可也。故又戒之以求助，抑之以下賢。</p></li><li><p>錢氏志立曰：小過所惡者，飛鳥也。鳥在穴而不飛，所謂不宜上而宜下者也。故公弋取以為助。</p></li></ul><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>小過有飛鳥之象，而所惡者飛，蓋飛則上而不下，違乎不宜上宜下之義也。雲亦飛物也，下而降則為雨。密雲不雨，是猶飛而未下也。五在上體，又居尊位，當小過之時，上而未下者也。故取宻雲不雨為象。雲而不雨，則膏澤不下於民矣。以其虛中也，故能降心以從道，抑志以下交，如弋鳥然。不弋其飛者而弋其在穴者，如此則合乎宜下之義，而云之飛者不崇朝而為雨之潤矣。此爻變鳥之象而為雲者，以居尊位故也。</p><p>象曰：密雲不雨，已上也</p><h3 id="本義-13" tabindex="-1">本義 <a class="header-anchor" href="#本義-13" aria-label="Permalink to “本義”">​</a></h3><p>已上，太高也。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>陽降陰升，合則和而成雨。陰已在上，雲雖密豈能成雨乎？陰過不能成大之義也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li>龔氏煥曰 ：密雲不雨，小畜謂其尚往者，陰不足以畜陽而陽尚往也；小過謂其已上者，陰過乎陽而陰已上也。一為陽之過，一為陰之過，皆陰陽不和之象，所以不能為雨也。案兩卦密雲不雨，龔氏謂皆陰陽不和之象是已然。小畜所謂尚往者，亦是陰氣上行，與此爻已上同，非兩義也。但小畜卦義喻在下者，則尚往者當積厚而自雨；此爻之義喻在上者，則已上者當下交而乃雨，意義不同爾。</li></ul><p>上六：弗遇過之，飛鳥離之，兇，是謂災眚。</p><h3 id="本義-14" tabindex="-1">本義 <a class="header-anchor" href="#本義-14" aria-label="Permalink to “本義”">​</a></h3><p>六以陰居動體之上，處陰過之極，過之已高而甚遠者也，故其象佔如此。或曰“遇過”恐亦只當作“過遇”，義同九四，未知是否。</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>六陰而動體，處過之極，不與理遇，動皆過之。其違理過常，如飛鳥之迅速，所以兇也。離過之遠，是謂災眚，是當有災眚也。災者，天殃；眚者，人為。既過之極，豈惟人眚，天災亦至，其兇可知。天理人事皆然也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：小人之過，遂至上極。過而不知限，至於亢也。過至於亢，將何所遇？飛而不將，何所託？災已自致，復何言哉。</p></li><li><p>孔氏穎達曰：以小人之身，過而弗遇，必遭羅網。其猶鳥飛而無託，必離繒繳，故曰“飛鳥離之兇也”。過亢離兇，是謂自災而致眚。</p></li><li><p>胡氏瑗曰：上六過而不已，若鳥之高翔，不知所止，以至窮極而離於兇禍，不能反於下以圖其所安。猶人之不近人情，亢已而行，故外來之災自招之，損皆有之也。</p></li><li><p>餘氏芑舒曰：飛鳥離之，如鴻則離之之離。</p></li><li><p>俞氏琰曰：彖辭言“不宜上而上”，乃震動之體，動極而忘返，如飛鳥離於繒繳，不亦兇乎？是天災也，亦人眚也，故曰“飛鳥離之兇，是謂災眚”。</p></li></ul><h3 id="案-10" tabindex="-1">案 <a class="header-anchor" href="#案-10" aria-label="Permalink to “案”">​</a></h3><p>復之上曰“迷復兇，有災眚”，此曰“飛鳥離之兇，是謂災眚”。辭意不同，兇由己作，災眚外至。迷復則因兇而致災眚者也，此則兇即其災眚也。蓋時當過極，不能自守而徇俗，以至於此。與初六當時未過而自飛以致兇者稍別。</p><p>象曰：弗遇過之，已亢也</p><h3 id="程傳-18" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-18" aria-label="Permalink to “程傳”">​</a></h3><p>居過之終，弗遇於理，而過之，過已亢，極其兇宜也。</p><h3 id="集說-16" tabindex="-1">集說 <a class="header-anchor" href="#集說-16" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：釋所以弗遇過之，以其已在亢極之地故也。</p></li><li><p>趙氏汝梅曰 ：已上未為極，已亢則極矣。</p></li><li><p>俞氏琰曰 ：六五曰已上，謂其已過也；上六又過甚，故曰已亢。</p></li></ul><p>總論</p><ul><li><p>項氏安世曰：坎離者，乾坤之用也。故上經終於坎離，下經終於既未濟。頤中孚肖離，大小過肖坎。故上經以頤大過附坎離，下經以中孚小過附既未濟。二陽函四陰則謂之頤，四陽函二陰則謂之中孚，二陰函四陽則謂之大過，四陰函二陽則謂之小過。離之為麗，坎之為陷，意亦類此。</p></li><li><p>吳氏曰：以二陽言，九三過剛居上，不能自下，故或戕之；九四居柔能下，故無咎。五上皆以陰乘陽，上彖傳所謂“上逆”者也。曰已上，曰已亢，然上兇而五不然者，以其柔中也。六二柔順中正而承乎陽，所謂“下順”者也，故無咎。初以柔居下而兇者，位雖卑而志則上而不下，是以與上六同為飛鳥之象也。</p></li></ul>',146)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
